function isSafeWorkspaceStatusUrl(value) {
  try {
    const u = new URL(value);
    if (!["https:", "http:"].includes(u.protocol) || u.username || u.password) return false;
    if (u.port && u.port !== (u.protocol === "https:" ? "443" : "80")) return false;
    const host = u.hostname.toLowerCase().replace(/\\.$/, "");
    if (!host || host === "localhost" || host.endsWith(".localhost") || host.endsWith(".local") ||
        host.endsWith(".internal") || host.endsWith(".lan") || host.endsWith(".home") ||
        host.endsWith(".test") || host.endsWith(".invalid") || host === "metadata.google.internal" ||
        host.includes(":") || /^\\d{1,3}(?:\\.\\d{1,3}){3}$/.test(host) ||
        !/^[a-z0-9.-]+$/.test(host) || !host.includes(".") || host.length > 253) return false;
    return host.split(".").every(function(label){ return label.length > 0 && label.length <= 63 && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label); });
  } catch (_) {
    return false;
  }
}

async function workspaceSiteStatus(request) {
  const json = function(data, status) {
    return new Response(JSON.stringify(data), {
      status: status || 200,
      headers: {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "X-Content-Type-Options": "nosniff"
      }
    });
  };
  if (request.method !== "GET") return json({ error: "GETリクエストのみ利用できます。" }, 405);
  const raw = new URL(request.url).searchParams.get("url") || "";
  if (!raw || raw.length > 1800 || !isSafeWorkspaceStatusUrl(raw)) {
    return json({ error: "公開サイトのHTTP / HTTPS URLを入力してください。IPアドレスやローカルネットワークは確認できません。" }, 400);
  }

  const started = Date.now();
  async function requestTarget(method) {
    let target = new URL(raw);
    for (let attempt = 0; attempt < 4; attempt++) {
      if (!isSafeWorkspaceStatusUrl(target.href)) throw new Error("リダイレクト先のURLは確認できません。");
      const controller = new AbortController();
      const timer = setTimeout(function(){ controller.abort(); }, 8000);
      let response;
      try {
        response = await fetch(target.href, {
          method: method,
          redirect: "manual",
          signal: controller.signal,
          headers: method === "GET" ? { "Range": "bytes=0-0", "User-Agent": "KURO-Lab-Site-Check/1.0" } : { "User-Agent": "KURO-Lab-Site-Check/1.0" }
        });
      } finally {
        clearTimeout(timer);
      }
      if ([301, 302, 303, 307, 308].includes(response.status)) {
        const location = response.headers.get("Location");
        if (!location || attempt === 3) {
          if (response.body) await response.body.cancel().catch(function(){});
          throw new Error("リダイレクトが多すぎます。");
        }
        const next = new URL(location, target);
        if (response.body) await response.body.cancel().catch(function(){});
        target = next;
        continue;
      }
      return { response: response, target: target };
    }
    throw new Error("サイトに接続できませんでした。");
  }

  try {
    let result = await requestTarget("HEAD");
    if (result.response.status === 405 || result.response.status === 501) {
      if (result.response.body) await result.response.body.cancel().catch(function(){});
      result = await requestTarget("GET");
    }
    const response = result.response;
    const payload = {
      ok: response.status >= 200 && response.status < 400,
      status: response.status,
      statusText: response.statusText || "",
      finalUrl: result.target.href,
      elapsedMs: Date.now() - started,
      checkedAt: new Date().toISOString()
    };
    if (response.body) await response.body.cancel().catch(function(){});
    return json(payload, 200);
  } catch (error) {
    const message = error && error.name === "AbortError" ? "接続がタイムアウトしました。" :
      (error && error.message ? error.message : "サイトに接続できませんでした。");
    return json({ error: message, elapsedMs: Date.now() - started }, 502);
  }
}


function isSafeWorkspaceRssUrl(value) {
  let target;
  try { target = new URL(value); } catch (_) { return false; }
  if (target.protocol !== "https:" && target.protocol !== "http:") return false;
  if (target.username || target.password) return false;
  if (target.port && target.port !== "80" && target.port !== "443") return false;
  const host = target.hostname.toLowerCase().replace(/^\[|\]$/g, "");
  if (!host || host === "localhost" || !host.includes(".") ||
      /(^|\.)(localhost|local|internal|test|invalid|example)$/.test(host) ||
      host.endsWith(".localhost") || host.endsWith(".local")) return false;
  if (/^[0-9.]+$/.test(host) || host.includes(":")) return false;
  return true;
}

async function workspaceRss(request) {
  const jsonError = (message, status) => new Response(JSON.stringify({ error: message }), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }
  });
  if (request.method !== "GET") return jsonError("GETリクエストのみ対応しています。", 405);
  const raw = new URL(request.url).searchParams.get("url") || "";
  if (!raw || raw.length > 1800 || !isSafeWorkspaceRssUrl(raw)) return jsonError("有効な公開HTTP / HTTPSフィードURLを指定してください。", 400);
  let target = new URL(raw);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 10000);
  try {
    let response = null;
    for (let attempt = 0; attempt < 5; attempt++) {
      if (!isSafeWorkspaceRssUrl(target.href)) return jsonError("安全でないリダイレクト先が検出されました。", 400);
      response = await fetch(target.href, {
        method: "GET", redirect: "manual", signal: controller.signal,
        headers: { "Accept": "application/rss+xml, application/atom+xml, application/xml, text/xml, */*;q=0.8", "User-Agent": "KURO-Lab-RSS/1.0" }
      });
      if (![301, 302, 303, 307, 308].includes(response.status)) break;
      const location = response.headers.get("Location");
      if (response.body) await response.body.cancel().catch(() => {});
      if (!location || attempt === 4) return jsonError("リダイレクトが多すぎます。", 502);
      target = new URL(location, target);
    }
    if (!response || !response.ok) {
      const status = response ? response.status : 502;
      if (response && response.body) await response.body.cancel().catch(() => {});
      return jsonError("配信元がフィードを返しませんでした（HTTP " + status + "）。", 502);
    }
    const length = Number(response.headers.get("Content-Length") || 0);
    if (length > 1500000) {
      if (response.body) await response.body.cancel().catch(() => {});
      return jsonError("フィードのサイズが上限を超えています。", 413);
    }
    const body = await response.text();
    if (new TextEncoder().encode(body).byteLength > 1500000) return jsonError("フィードのサイズが上限を超えています。", 413);
    if (!body.trim()) return jsonError("配信元から空のフィードが返されました。", 502);
    return new Response(body, { status: 200, headers: {
      "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=300, s-maxage=300", "X-Content-Type-Options": "nosniff"
    }});
  } catch (error) {
    return jsonError(error && error.name === "AbortError" ? "フィード取得がタイムアウトしました。" : "フィード配信元に接続できませんでした。", 502);
  } finally {
    clearTimeout(timer);
  }
}

export default {
  async fetch(request, env, ctx) {
    try {
    const url = new URL(request.url);

    if (url.pathname === "/favicon.ico") {
      const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="15" fill="#101827"/><path d="M16 12h9v18l17-18h12L36 31l19 21H43L25 35v17h-9z" fill="#55b5f2"/><path d="M25 30l11 1-11 4z" fill="#dff3ff"/></svg>';
      return new Response(svg, { status: 200, headers: { "Content-Type": "image/svg+xml; charset=utf-8", "Cache-Control": "public, max-age=86400", "X-Content-Type-Options": "nosniff" } });
    }

    if (url.hostname === "kurolab.cc.cd" && (url.pathname === "/pro" || url.pathname === "/pro/")) {
      const assetUrl = new URL("/pro/index.html", request.url);
      const assetResponse = await env.ASSETS.fetch(new Request(assetUrl, { method: "GET", headers: request.headers }));
      if (assetResponse.status !== 404) {
        const headers = new Headers(assetResponse.headers);
        headers.set("Cache-Control", "private, no-store, max-age=0");
        headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
        headers.set("X-Content-Type-Options", "nosniff");
        return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
      }
      return new Response(PRO_HTML, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store, max-age=0", "X-Content-Type-Options": "nosniff" } });
    }

    if (url.hostname === "kurolab.cc.cd" && (url.pathname === "/pro-tools" || url.pathname === "/pro-tools/")) {
      const assetUrl = new URL("/pro-tools/index.html", request.url);
      const assetResponse = await env.ASSETS.fetch(new Request(assetUrl, { method: "GET", headers: request.headers }));
      const headers = new Headers(assetResponse.headers);
      headers.set("Cache-Control", "private, no-store, max-age=0");
      headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
      headers.set("X-Content-Type-Options", "nosniff");
      if (assetResponse.status !== 404) return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
      return new Response("Not Found", { status: 404, headers });
    }

    if (url.hostname === "kurolab.cc.cd" && url.pathname === "/portal.css") {
      const assetResponse = await env.ASSETS.fetch(request);
      if (assetResponse.status !== 404) {
        const headers = new Headers(assetResponse.headers);
        headers.set("Content-Type", "text/css; charset=utf-8");
        headers.set("Cache-Control", "no-store, max-age=0");
        headers.set("X-Content-Type-Options", "nosniff");
        return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
      }
      return new Response(PORTAL_CSS, { headers: { "Content-Type": "text/css; charset=utf-8", "Cache-Control": "no-store, max-age=0", "X-Content-Type-Options": "nosniff" } });
    }

    if (url.hostname === "kurolab.cc.cd" && url.pathname === "/portal.js") {
      const assetResponse = await env.ASSETS.fetch(request);
      if (assetResponse.status !== 404) {
        const headers = new Headers(assetResponse.headers);
        headers.set("Content-Type", "application/javascript; charset=utf-8");
        headers.set("Cache-Control", "no-store, max-age=0");
        headers.set("X-Content-Type-Options", "nosniff");
        return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
      }
      return new Response(PORTAL_JS, { headers: { "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "no-store, max-age=0", "X-Content-Type-Options": "nosniff" } });
    }

    if (url.hostname === "kurolab.cc.cd" && (url.pathname === "/admin" || url.pathname === "/admin/")) {
      const headers = new Headers({
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "private, no-store, max-age=0",
        "X-Robots-Tag": "noindex, nofollow, noarchive",
        "X-Content-Type-Options": "nosniff",
        "Referrer-Policy": "same-origin",
        "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
        "X-Frame-Options": "DENY",
        "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
      });
      return new Response(ADMIN_HTML, { status: 200, headers });
    }

    if (url.hostname === "kurolab.cc.cd" && url.pathname === "/") {
      const response = await env.ASSETS.fetch(request);
      const html = await response.text();
      const updated = html.includes("href=\"/admin/\"") ? html : html.replace("<a href=\"/contact/\">お問い合わせ</a>", "<a href=\"/contact/\">お問い合わせ</a><a href=\"/admin/\">管理者</a>");
      const headers = new Headers(response.headers);
      headers.set("Cache-Control", "no-store");
      return new Response(updated, { status: response.status, statusText: response.statusText, headers });
    }

    if (url.hostname === "admin.kurolab.cc.cd") {
      if (url.pathname === "/" || url.pathname === "/admin/index.html") {
        const assetUrl = new URL("/admin/index.html", request.url);
        const assetResponse = await env.ASSETS.fetch(new Request(assetUrl, { method: "GET", headers: request.headers }));
        const headers = new Headers(assetResponse.headers);
        headers.set("Cache-Control", "private, no-store, max-age=0");
        headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
        headers.set("X-Content-Type-Options", "nosniff");
        headers.set("Referrer-Policy", "same-origin");
        headers.set("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
        headers.set("X-Frame-Options", "DENY");
        headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
        if (assetResponse.status !== 404) return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
        return new Response(ADMIN_HTML, { status: 200, headers: { ...Object.fromEntries(headers), "Content-Type": "text/html; charset=utf-8" } });
      }
      const response = await env.ASSETS.fetch(request);
      const headers = new Headers(response.headers);
      headers.set("Cache-Control", "private, no-store, max-age=0");
      headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
      headers.set("X-Content-Type-Options", "nosniff");
      return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers
      });
    }

    if (url.hostname === "kurolab.cc.cd" && url.pathname === "/api/site-status") {
      return await workspaceSiteStatus(request);
    }

    if (url.pathname === "/api/workspace-rss") {
      return await workspaceRss(request);
    }

    if (url.pathname === "/api/kuro-gas-proxy") {
      return await gasProxy({
        request,
        env,
        params: {},
        waitUntil: (promise) => ctx.waitUntil(promise),
        next: () => env.ASSETS.fetch(request)
      });
    }

    return await env.ASSETS.fetch(request);
    } catch (error) {
      let pathname = "/";
      try { pathname = new URL(request.url).pathname; } catch (_) {}
      const rayId = request.headers.get("cf-ray") || "not-provided";
      const errorName = error && error.name ? String(error.name) : "Error";
      const rawMessage = String(error && error.message ? error.message : error || "Unknown error");
      const errorMessage = rawMessage.replace(/https?:\/\/\S+/g, (value) => {
        const queryIndex = value.indexOf("?");
        return queryIndex < 0 ? value : value.slice(0, queryIndex) + "?[redacted]";
      }).slice(0, 1200);
      const errorStack = error && typeof error.stack === "string" ? error.stack.slice(0, 6000) : "";
      console.error("[KURO_LAB_WORKER_EXCEPTION]", JSON.stringify({
        rayId,
        method: request.method,
        pathname,
        errorName,
        errorMessage,
        stack: errorStack
      }));
      return new Response("KURO Lab is temporarily unavailable. Please try again shortly.", {
        status: 503,
        headers: {
          "Content-Type": "text/plain; charset=utf-8",
          "Cache-Control": "no-store",
          "Retry-After": "30",
          "X-Content-Type-Options": "nosniff",
          "X-Kuro-Error": "worker-exception",
          "X-Kuro-Request-Id": rayId
        }
      });
    }
  }
};
